#!/usr/bin/env bash
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing Figure-1 collapse-map script..."
decode "scripts/paper_fig1_collapse_map.py" << 'B64EOF'

B64EOF
echo "Installed. Run:  python scripts/paper_fig1_collapse_map.py"